<template>
  <section class="collections" v-loading="busy"><header><div><h2>学生材料收集</h2></div><div><el-button @click="load" :loading="busy">刷新</el-button><template v-if="staff"><el-button @click="openTemplate()">管理填写表单</el-button><el-button type="primary" @click="openCreate">发起材料收集</el-button></template></div></header><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <div v-if="staff && templates.length" class="template-strip"><span>可用表单：</span><el-button v-for="t in templates" :key="t.id" size="small" @click="openTemplate(t)">{{t.name}} （修改副本）</el-button></div>
    <div v-if="items.length" class="collection-filters">
      <el-radio-group v-model="collectionScope" aria-label="材料收集范围"><el-radio-button label="current">当前收集</el-radio-button><el-radio-button label="history">历史收集</el-radio-button><el-radio-button label="all">全部</el-radio-button></el-radio-group>
      <el-input v-model="collectionSearch" clearable placeholder="搜索收集名称或要求" aria-label="搜索材料收集" />
    </div>
    <el-empty v-if="!busy && !error && !items.length" :description="staff?'暂无材料收集，点击右上角“发起材料收集”开始':'暂时没有需要提交的材料'" />
    <el-empty v-else-if="!busy && !error && !visibleCollections.length" :description="collectionSearch.trim()?'没有找到匹配的材料收集':collectionScope==='history'?'暂无已归档的材料收集':'当前没有正在办理的材料收集'"><el-button @click="collectionSearch='';collectionScope='all'">查看全部收集</el-button></el-empty>
    <div class="cards"><article v-for="c in visibleCollections" :key="c.id" class="card"><div class="heading"><h3>{{c.name}}</h3><el-tag>{{stateLabel(c.status)}}</el-tag></div><p>{{c.purpose}}</p><p class="meta">{{fmt(c.startAt)}} — {{fmt(c.dueAt)}} · {{c.requiresReview?'审核通过后完成':'提交后完成'}}</p><p class="meta">资料可见范围：{{c.visibility}}</p><p v-if="c.counts" class="counts">未交 {{c.counts.unsubmitted}} · 待审 {{c.counts.pending_review}} · 退回 {{c.counts.returned}} · 已完成 {{c.counts.submitted+c.counts.approved}} · 免交 {{c.counts.exempt}}<br>其中逾期 {{c.counts.overdue}} · 已移出名单 {{c.counts.removed}}</p><el-button type="primary" @click="open(c)">{{user.role==='student'?'填写材料':'查看提交情况'}}</el-button><el-button v-if="pendingReviewCount(c)" @click="open(c,'pending_review')">审核材料（{{pendingReviewCount(c)}}）</el-button><el-button v-if="c.canManage && c.status==='draft'" @click="act(c,'publish')">确认发布</el-button></article></div>
    <el-dialog v-model="templateOpen" title="学生填写表单" width="min(96vw, 860px)" :close-on-click-modal="false">
      <el-form label-position="top">
        <el-form-item label="表单名称" required><el-input v-model="templateForm.name" placeholder="例如：班级联系方式登记" maxlength="100" /></el-form-item>
        <el-checkbox v-model="templateForm.shared">其他辅导员也可以使用这份表单</el-checkbox>
        <article class="field-card" v-for="(f,i) in templateForm.fields" :key="f.key || 'field-'+i">
          <div class="field-heading"><strong>第 {{ i + 1 }} 项</strong><el-button size="small" type="danger" text @click="templateForm.fields.splice(i,1)"><el-icon><Delete /></el-icon>删除</el-button></div>
          <div class="grid">
            <el-form-item label="问题名称" required><el-input v-model="f.label" placeholder="例如：联系电话" maxlength="100" /></el-form-item>
            <el-form-item label="学生填写方式"><el-select v-model="f.type"><el-option v-for="t in fieldTypes" :key="t.value" :value="t.value" :label="t.label" /></el-select></el-form-item>
          </div>
          <el-form-item v-if="['radio','multi','select'].includes(f.type)" label="可选答案" required><el-input v-model="f.optionText" placeholder="多个答案用逗号分隔" /></el-form-item>
          <el-form-item label="补充说明"><el-input v-model="f.description" placeholder="可填写材料要求或注意事项" maxlength="500" /></el-form-item>
          <el-checkbox v-model="f.required">学生必须填写</el-checkbox>
          <el-collapse><el-collapse-item title="自动填写与格式要求（可选）">
            <div class="grid">
              <el-form-item label="从学生档案自动填写"><el-select v-model="f.profileField" clearable placeholder="不自动填写"><el-option v-for="p in profileFields" :key="p.value" :value="p.value" :label="p.label" /></el-select></el-form-item>
              <el-form-item label="答案格式"><el-select v-model="f.format" clearable placeholder="不限"><el-option label="手机号" value="phone" /><el-option label="邮箱" value="email" /><el-option label="学号" value="studentNo" /></el-select></el-form-item>
              <el-form-item label="最少字数"><el-input v-model="f.minLength" type="number" min="0" placeholder="不限" /></el-form-item>
              <el-form-item label="最多字数"><el-input v-model="f.maxLength" type="number" min="0" placeholder="不限" /></el-form-item>
              <el-form-item v-if="f.type==='number'" label="最小数值"><el-input v-model="f.min" type="number" placeholder="不限" /></el-form-item>
              <el-form-item v-if="f.type==='number'" label="最大数值"><el-input v-model="f.max" type="number" placeholder="不限" /></el-form-item>
            </div>
          </el-collapse-item></el-collapse>
        </article>
        <el-button @click="addField"><el-icon><Plus /></el-icon>添加问题</el-button>
      </el-form>
      <template #footer><el-button @click="templateOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveTemplate">保存表单</el-button></template>
    </el-dialog>
    <el-dialog v-model="createOpen" title="发起学生材料收集" width="min(96vw, 780px)" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="任务名称" required><el-input v-model="form.name" /></el-form-item><el-form-item label="需要学生提交什么" required><el-input v-model="form.purpose" type="textarea" /></el-form-item><el-form-item label="学生填写表单" required><el-select v-model="form.templateId" placeholder="选择表单"><el-option v-for="t in templates" :key="t.id" :value="t.id" :label="t.name" /></el-select><el-button text type="primary" @click="openTemplate()">新建填写表单</el-button></el-form-item><div class="preview" v-if="selectedTemplate"><strong>学生视角预览</strong><p v-for="f in selectedTemplate.fields" :key="f.key">{{f.required?'* ':''}}{{f.label}} · {{fieldTypes.find(t=>t.value===f.type)?.label}} <span v-if="f.profileField">（自动填写{{profileFields.find(p=>p.value===f.profileField)?.label || '档案资料'}}）</span><small>{{f.description}}</small></p></div><el-form-item label="需要提交的学生" required><el-select v-model="form.studentIds" multiple filterable collapse-tags placeholder="按姓名或班级搜索"><el-option v-for="s in students" :key="s.id" :value="s.id" :label="`${s.name} · ${s.className}`" /></el-select><div class="selection-actions"><el-button text @click="form.studentIds=students.map(s=>s.id)">选择全部 {{students.length}} 名学生</el-button><el-button text @click="form.studentIds=[]">清空选择</el-button></div></el-form-item><p>已选择 {{form.studentIds.length}} 名学生，由你负责收集和审核。保存后可核对名单，再发布给学生。</p><div class="grid"><el-form-item label="开始时间（北京时间）" required><el-input v-model="form.startAt" type="datetime-local" /></el-form-item><el-form-item label="截止时间（北京时间）" required><el-input v-model="form.dueAt" type="datetime-local" /></el-form-item></div><el-form-item label="资料用途与可见范围" required><el-input v-model="form.visibility" placeholder="例如：仅本班辅导员核验，用于本次材料收交" /></el-form-item><el-checkbox v-model="form.requiresReview">需要审核，通过后才完成</el-checkbox><el-checkbox v-model="form.allowSupplement">允许负责人为指定学生开放补交窗口</el-checkbox></el-form><template #footer><el-button @click="createOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="create">保存草稿并核对名单</el-button></template></el-dialog>
    <el-dialog v-model="detailOpen" :title="current?.name||'材料收集详情'" width="min(96vw, 1100px)" :close-on-click-modal="false"><template v-if="current"><p>{{current.purpose}}</p><p class="meta">{{stateLabel(current.status)}} · 截止 {{fmt(current.dueAt)}} · {{current.visibility}}</p>
      <template v-if="user.role==='student' && ownRow"><el-alert v-if="ownRow.status!=='required'" :title="ownRow.status==='exempt'?'你已获免交：'+ownRow.changeReason:'已移出本次名单，历史仍保留'" type="info" :closable="false" /><el-alert v-if="answerHint" :title="answerHint" type="info" :closable="false" show-icon /><p>提交状态：{{answerLabel(ownRow.answer.status)}} <span v-if="ownRow.answer.receipt"> · 回执 {{ownRow.answer.receipt}}</span></p><p v-if="isReviewed(ownRow.answer) && ownRow.answer.reviewReason">审核意见：{{ownRow.answer.reviewReason}}</p><p v-if="ownRow.supplementaryUntil">补交截止：{{fmt(ownRow.supplementaryUntil)}}</p><el-form label-position="top"><el-form-item v-for="f in current.fields" :key="f.key" :label="f.label" :required="f.required"><div class="field-full"><p v-if="current.prefill?.[f.key]" class="meta">已从学生档案自动填写 · 更新 {{fmt(current.prefill[f.key].updatedAt)}}；若正式资料不符，请在“我的学生档案”申请更正。</p><MaterialUpload v-if="f.type==='attachment'" v-model="answerValues[f.key]" :readonly="!answerEditable" :disabled="busy" @busy="uploadStates[f.key]=$event" /><el-input v-else-if="['text','textarea','number','date'].includes(f.type)" v-model="answerValues[f.key]" :type="f.type==='textarea'?'textarea':f.type==='number'?'number':f.type==='date'?'date':'text'" :disabled="!answerEditable" :rows="3" /><el-checkbox-group v-else-if="f.type==='multi'" v-model="answerValues[f.key]" :disabled="!answerEditable"><el-checkbox v-for="o in f.options" :key="o" :label="o" /></el-checkbox-group><el-radio-group v-else-if="f.type==='radio'" v-model="answerValues[f.key]" :disabled="!answerEditable"><el-radio v-for="o in f.options" :key="o" :label="o" /></el-radio-group><el-select v-else v-model="answerValues[f.key]" :disabled="!answerEditable"><el-option v-for="o in f.options" :key="o" :label="o" :value="o" /></el-select><small>{{f.description}}</small></div></el-form-item></el-form><div v-if="answerEditable"><el-button :disabled="uploadBusy" :loading="busy" @click="saveAnswer(false)">保存草稿</el-button><el-button type="primary" :disabled="uploadBusy" :loading="busy" @click="saveAnswer(true)">确认提交</el-button><span v-if="draftSaved" class="meta">上次保存 {{draftSaved}}</span></div><el-collapse><el-collapse-item title="历史提交与审核记录"><p v-if="!ownRow.answer.history?.length" class="meta">暂无历史记录</p><article v-for="(h,i) in ownRow.answer.history" :key="i" class="answer-history"><strong>{{answerLabel(h.status)}} · {{fmt(answerTime(h))}}</strong><p v-if="isReviewed(h) && h.reviewReason">审核意见：{{h.reviewReason}}</p><div v-for="f in current.fields" :key="f.key" class="answer-line"><strong>{{f.label}}</strong><MaterialUpload v-if="f.type==='attachment'" :model-value="h.values?.[f.key]||[]" readonly /><p v-else>{{answerText(h.values?.[f.key])}}</p></div></article></el-collapse-item></el-collapse></template>
      <template v-else><div class="toolbar" v-if="current.canManage"><el-button v-if="current.status==='draft'" @click="act(current,'publish')">确认发布</el-button><el-button v-if="['active','expired'].includes(current.status)" @click="act(current,'extend')">延期</el-button><el-button v-if="['active','expired'].includes(current.status)" @click="act(current,'close')">关闭归档</el-button><el-button v-if="!['closed','cancelled'].includes(current.status)" @click="act(current,'cancel')">取消任务</el-button><el-button v-if="current.status==='closed'" @click="act(current,'reopen')">重新开放收集</el-button><el-button v-if="!['closed','cancelled'].includes(current.status)" @click="openRoster">调整名单 / 免交 / 补交</el-button><el-button @click="copyTask">复制为新任务</el-button></div><p v-if="user.role==='admin'" class="meta">账号管理员仅查看任务配置和汇总，不读取学生答卷正文。</p><div class="roster-filters" v-else><el-input v-model="rosterSearch" clearable placeholder="搜索学生姓名或学号" aria-label="搜索提交学生" /><el-select v-model="rosterClass" clearable filterable placeholder="全部班级" aria-label="按班级筛选材料"><el-option v-for="className in rosterClasses" :key="className" :value="className" :label="className" /></el-select><el-select v-model="category" clearable placeholder="按收交状态筛选" aria-label="按收交状态筛选"><el-option v-for="(v,k) in categories" :key="k" :value="k" :label="v" /></el-select><el-button v-if="rosterFiltered" text @click="clearRosterFilters">清空筛选</el-button></div><p v-if="user.role!=='admin'" class="meta" aria-live="polite">显示 {{visibleRoster.length}} 名学生 / 可查看 {{current.roster?.length || 0}} 名</p><div v-if="user.role!=='admin'" class="toolbar"><el-button :loading="busy" @click="startExport">导出名单与材料清单</el-button><el-button v-if="exportJob" @click="refreshExport">刷新导出状态</el-button><span v-if="exportJob">{{exportStates[exportJob.status] || '处理中'}} · {{exportJob.progress}}%</span><el-button v-if="exportJob?.status==='ready'" @click="downloadExport">下载（15分钟有效）</el-button></div><p v-if="user.role!=='admin'" class="meta">导出包含完整名单和填写内容，附件以文件清单列出；当前筛选仅用于查看。</p><el-table :data="visibleRoster" :empty-text="rosterFiltered?'没有找到符合条件的学生，可清空筛选查看全部':'暂无可查看的学生材料'"><el-table-column prop="studentNo" label="学号" min-width="130" /><el-table-column prop="name" label="姓名" min-width="100" /><el-table-column prop="className" label="班级" min-width="140" /><el-table-column label="状态" min-width="140"><template #default="{row}">{{categories[row.category]||row.category}}{{row.overdue?' · 逾期':''}}</template></el-table-column><el-table-column label="回执" min-width="180"><template #default="{row}">{{row.answer.receipt||'尚未提交'}}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button @click="openReview(row)">查看材料</el-button></template></el-table-column></el-table><el-collapse><el-collapse-item title="名单与任务操作历史"><p v-for="(h,i) in current.history" :key="i">{{fmt(h.at)}} · {{actionLabel(h.action)}} · {{h.reason}}</p></el-collapse-item><el-collapse-item title="历次截止与名单记录"><p v-for="(s,i) in current.snapshots" :key="i">{{fmt(s.at)}} · {{s.reason}} · 原截止 {{fmt(s.dueAt)}} · {{s.rows.length}}人</p></el-collapse-item></el-collapse></template>
    </template></el-dialog>
    <el-dialog :model-value="!!reviewRow" @close="reviewRow=undefined" title="学生材料审核" width="min(95vw,780px)"><template v-if="reviewRow"><p>{{reviewRow.name}} · {{answerLabel(reviewRow.answer.status)}} · {{reviewRow.answer.receipt}}</p><div v-for="f in current.fields" :key="f.key" class="answer-line"><strong>{{f.label}}</strong><MaterialUpload v-if="f.type==='attachment'" :model-value="reviewRow.answer.values[f.key]||[]" readonly /><p v-else>{{answerText(reviewRow.answer.values[f.key])}}</p></div><p v-if="isReviewed(reviewRow.answer) && reviewRow.answer.reviewReason">审核意见：{{reviewRow.answer.reviewReason}}</p><p v-if="reviewRow.answer.status==='pending_review' && !canReviewAnswer(reviewRow)" class="meta">当前名单或收集任务已结束，仅供查看材料与审核历史。</p><template v-if="canReviewAnswer(reviewRow)"><el-input v-model="reviewReason" type="textarea" placeholder="通过依据或退回原因（必填）" /><el-button type="primary" :loading="busy" @click="review(true)">审核通过</el-button><el-button :loading="busy" @click="review(false)">退回修改</el-button></template><el-collapse><el-collapse-item title="历史版本"><p v-if="!reviewRow.answer.history?.length" class="meta">暂无历史记录</p><article v-for="(h,i) in reviewRow.answer.history" :key="i" class="answer-history"><strong>{{answerLabel(h.status)}} · {{fmt(answerTime(h))}}</strong><p v-if="isReviewed(h) && h.reviewReason">审核意见：{{h.reviewReason}}</p><div v-for="f in current.fields" :key="f.key" class="answer-line"><strong>{{f.label}}</strong><MaterialUpload v-if="f.type==='attachment'" :model-value="h.values?.[f.key]||[]" readonly /><p v-else>{{answerText(h.values?.[f.key])}}</p></div></article></el-collapse-item></el-collapse></template></el-dialog>
    <el-dialog v-model="rosterOpen" title="调整学生名单与补交时间" width="min(95vw,550px)"><el-form label-position="top"><el-form-item label="学生"><el-select v-model="rosterForm.studentId" filterable><el-option v-for="s in students" :key="s.id" :label="`${s.name} · ${s.className}`" :value="s.id" /></el-select></el-form-item><el-form-item label="操作"><el-select v-model="rosterForm.action"><el-option v-for="(label,value) in rosterActions" :key="value" :value="value" :label="label" /></el-select></el-form-item><el-form-item v-if="rosterForm.action==='supplement'" label="补交截止时间（北京时间）"><el-input v-model="rosterForm.until" type="datetime-local" /></el-form-item><el-form-item label="调整原因" required><el-input v-model="rosterForm.reason" type="textarea" /></el-form-item><el-button type="primary" :loading="busy" @click="changeRoster">保存调整</el-button></el-form></el-dialog>
    <el-dialog v-model="maintenanceOpen" :title="maintenance.action==='extend'?'延长提交时间':'重新开放收集'" width="min(95vw, 520px)" :close-on-click-modal="false"><p>{{maintenance.name}}</p><p class="meta">原截止时间：{{fmt(maintenance.originalDueAt)}}</p><el-form label-position="top"><el-form-item :label="maintenance.action==='extend'?'新的截止时间（北京时间）':'新的截止时间（可选，北京时间）'" :required="maintenance.action==='extend'"><el-input v-model="maintenance.dueAt" type="datetime-local" /></el-form-item><p v-if="maintenance.action==='reopen'" class="meta">不设置新的截止时间时，将保留原截止时间；原截止已过时，需另外为指定学生开放补交。</p><el-form-item label="调整原因" required><el-input v-model="maintenance.reason" type="textarea" placeholder="例如：部分材料尚待核实，延长提交时间" /></el-form-item></el-form><template #footer><el-button @click="maintenanceOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveMaintenance">{{maintenance.action==='extend'?'保存新截止时间':'重新开放收集'}}</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import { csvCell } from '../../shared/csv';
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {api} from '@/api';import MaterialUpload from './MaterialUpload.vue';
let fieldSerial=0;
const maintenanceOpen=ref(false),maintenance=reactive({id:'',name:'',action:'extend',originalDueAt:'',dueAt:'',reason:''});
const now=ref(Date.now());let clockTimer:ReturnType<typeof setInterval>|undefined;
const exportStates:Record<string,string>={queued:'等待生成',processing:'正在生成',ready:'可以下载',failed:'生成失败'};
function openCreate(){Object.assign(form,{name:'',purpose:'',templateId:templates.value[0]?.id||'',studentIds:[],startAt:new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).replace(' ','T'),dueAt:'',requiresReview:true,allowSupplement:true});createOpen.value=true;}
const props=defineProps<{user:Record<string,any>;users:Record<string,any>[];initialRecordId?:string}>();const user=computed(()=>props.user),staff=computed(()=>['admin','counselor'].includes(user.value.role)),students=computed(()=>props.users.filter(u=>u.role==='student'&&u.enabled));const items=ref<any[]>([]),templates=ref<any[]>([]),busy=ref(false),error=ref(''),current=ref<any>(),detailOpen=ref(false),templateOpen=ref(false),createOpen=ref(false),reviewRow=ref<any>(),reviewReason=ref(''),category=ref(''),rosterOpen=ref(false),exportJob=ref<any>(),draftSaved=ref('');const uploadStates=reactive<Record<string,boolean>>({}),uploadBusy=computed(()=>Object.values(uploadStates).some(Boolean));
const fieldTypes=[{value:'text',label:'单行文本'},{value:'textarea',label:'多行文本'},{value:'number',label:'数字'},{value:'date',label:'日期'},{value:'radio',label:'单选'},{value:'multi',label:'多选'},{value:'select',label:'下拉'},{value:'attachment',label:'附件 / 照片 / 录屏'}];const profileFields=[{value:'name',label:'姓名'},{value:'studentNo',label:'学号'},{value:'className',label:'班级'},{value:'college',label:'学院'},{value:'major',label:'专业'},{value:'grade',label:'年级'},{value:'phone',label:'手机号'},{value:'email',label:'邮箱'}];const categories:Record<string,string>={unsubmitted:'未提交（含草稿）',submitted:'已提交 / 已完成',pending_review:'待审核',returned:'已退回',approved:'已通过',exempt:'免交',removed:'已移除（历史）'},rosterActions={add:'新增应交对象',remove:'移除并保留历史',exempt:'免交',restore:'恢复为应交对象',supplement:'开放指定补交窗口'};
const templateForm=reactive<any>({name:'',shared:false,copiedFrom:'',fields:[]}),form=reactive<any>({name:'',purpose:'',templateId:'',studentIds:[],startAt:'',dueAt:'',visibility:'仅授权辅导员及经审批的限时授权人员可查看，用于本次材料核验',requiresReview:true,allowSupplement:true}),rosterForm=reactive({studentId:'',action:'supplement',until:'',reason:''}),answerValues=reactive<Record<string,any>>({});const selectedTemplate=computed(()=>templates.value.find(t=>t.id===form.templateId)),ownRow=computed(()=>current.value?.roster?.find((r:any)=>r.studentId===user.value.id)),answerEditable=computed(()=>!!ownRow.value&&ownRow.value.status==='required'&&['draft','returned'].includes(ownRow.value.answer.status)&&!['draft','closed','cancelled'].includes(current.value.status)&&new Date(current.value.startAt).getTime()<=now.value&&(new Date(current.value.dueAt).getTime()>=now.value||new Date(ownRow.value.supplementaryUntil||'').getTime()>=now.value)),visibleRoster=computed(()=>{
  const keyword=rosterSearch.value.trim().toLocaleLowerCase();
  return (current.value?.roster||[]).filter((r:any)=>(!category.value||r.category===category.value)&&(!rosterClass.value||r.className===rosterClass.value)&&(!keyword||[r.name,r.studentNo].some(value=>String(value||'').toLocaleLowerCase().includes(keyword))));
});
const answerHint=computed(()=>{if(!ownRow.value||ownRow.value.status!=='required')return '';const answer=ownRow.value.answer.status;if(answer==='pending_review')return '材料已提交，等待辅导员审核，无需重复提交。';if(['submitted','approved'].includes(answer))return '本次材料已完成提交，可在下方查看内容和历史记录。';if(answerEditable.value)return answer==='returned'?'材料已退回，请按审核意见修改后重新提交。':'';if(current.value.status==='draft')return '材料收集尚未发布，请等待负责人通知。';if(['closed','cancelled'].includes(current.value.status))return '本次收集已结束，仅供查看历史材料。';if(new Date(current.value.startAt).getTime()>now.value)return '尚未到开始时间，请在 '+fmt(current.value.startAt)+' 后填写。';return '提交时间已结束。如需补交，请联系负责人开放补交时间。';});
function isReviewed(answer:any){return ['approved','returned'].includes(answer.status)}
function answerTime(answer:any){return isReviewed(answer)?(answer.reviewedAt||answer.updatedAt):['pending_review','submitted'].includes(answer.status)?(answer.submittedAt||answer.updatedAt):answer.updatedAt}
function answerText(value:any){if(value===undefined||value===null||value==='')return '未填写';return Array.isArray(value)?(value.length?value.join('、'):'未填写'):String(value);}
function actionLabel(action:string){return ({create:'创建草稿',publish:'发布收集',extend:'延长截止时间',close:'结束收集并归档',cancel:'取消收集',reopen:'重新开放收集','roster.add':'增加学生','roster.remove':'移出学生','roster.exempt':'设为免交','roster.restore':'恢复提交要求','roster.supplement':'开放补交'} as Record<string,string>)[action]||'任务调整';}
const collectionScope=ref('current'),collectionSearch=ref(''),rosterSearch=ref(''),rosterClass=ref('');
const visibleCollections=computed(()=>{
  const keyword=collectionSearch.value.trim().toLocaleLowerCase();
  return items.value.filter(c=>{
    const archived=['closed','cancelled'].includes(c.status);
    return (collectionScope.value==='all'||(collectionScope.value==='history'?archived:!archived))&&(!keyword||[c.name,c.purpose].some(value=>String(value||'').toLocaleLowerCase().includes(keyword)));
  });
});
const rosterClasses=computed<string[]>(()=>Array.from(new Set<string>((current.value?.roster||[]).map((r:any)=>String(r.className||'')).filter(Boolean))).sort((a,b)=>a.localeCompare(b,'zh-CN')));
const rosterFiltered=computed(()=>!!(category.value||rosterSearch.value.trim()||rosterClass.value));
function clearRosterFilters(){category.value='';rosterSearch.value='';rosterClass.value='';}
function canReviewAnswer(row:any,c=current.value){return !!c&&!['draft','closed','cancelled'].includes(c.status)&&row.status==='required'&&row.canReview&&row.answer?.status==='pending_review';}
function pendingReviewCount(c:any){return (c.roster||[]).filter((r:any)=>canReviewAnswer(r,c)).length;}
function openReview(row:any){reviewReason.value='';reviewRow.value=row;}
function openRoster(){Object.assign(rosterForm,{studentId:'',action:current.value?.allowSupplement?'supplement':'exempt',until:'',reason:''});rosterOpen.value=true;}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e:any){error.value=e.message;ElMessage.error(e.message)}finally{busy.value=false}}
async function refresh(){items.value=await api('/collections');if(staff.value)templates.value=await api('/collection-templates')}
async function load(){await run(refresh);await openInitial()}async function open(c:any,initialCategory=''){clearRosterFilters();category.value=initialCategory;reviewRow.value=undefined;for(const key of Object.keys(uploadStates))delete uploadStates[key];await run(async()=>{current.value=await api(`/collections/${c.id}`);detailOpen.value=true;exportJob.value=undefined;draftSaved.value='';for(const k of Object.keys(answerValues))delete answerValues[k];if(ownRow.value)for(const f of current.value.fields)answerValues[f.key]=ownRow.value.answer.values[f.key]??current.value.prefill?.[f.key]?.value??(['multi','attachment'].includes(f.type)?[]:'')})}
async function openInitial(){if(!props.initialRecordId)return;const item=items.value.find(c=>c.id===props.initialRecordId);if(item)await open(item);else if(!error.value)ElMessage.info('这项材料收集已变化，请在列表中查看最新安排');}
watch(()=>props.initialRecordId,openInitial);
function addField(){templateForm.fields.push({key:'f_'+Date.now().toString(36)+'_'+(++fieldSerial),label:'',type:'text',required:false,description:'',format:'',profileField:'',optionText:'',minLength:'',maxLength:'',min:'',max:''})}
function openTemplate(t?:any){Object.assign(templateForm,t?{name:t.name+'（修订）',shared:t.shared,copiedFrom:t.id,fields:t.fields.map((f:any)=>({...f,optionText:(f.options||[]).join('，')}))}:{name:'',shared:false,copiedFrom:'',fields:[]});if(!t)addField();templateOpen.value=true}
async function saveTemplate(){if(!templateForm.name.trim())return ElMessage.warning('请填写表单名称');if(!templateForm.fields.length)return ElMessage.warning('请至少添加一个问题');for(const [index,f] of templateForm.fields.entries()){if(!String(f.label||'').trim())return ElMessage.warning('请填写第 '+(index+1)+' 项的问题名称');if(['radio','select','multi'].includes(f.type)&&!String(f.optionText||'').trim())return ElMessage.warning('请填写“'+f.label+'”的可选答案');}await run(async()=>{const fields=templateForm.fields.map((f:any)=>{const value={...f};delete value.optionText;if(['radio','select','multi'].includes(f.type))value.options=[...new Set(f.optionText.split(/[,，\n]/).map((s:string)=>s.trim()).filter(Boolean))];return value});const t=await api('/collection-templates',{method:'POST',body:{...templateForm,fields}});form.templateId=t.id;templateOpen.value=false;await refresh();ElMessage.success('填写表单已保存')})}
async function create(){if(!form.name.trim())return ElMessage.warning('请填写材料收集名称');if(!form.purpose.trim())return ElMessage.warning('请填写需要学生提交的内容');if(!form.templateId)return ElMessage.warning('请选择或新建学生填写表单');if(!form.studentIds.length)return ElMessage.warning('请选择需要提交的学生');if(!form.startAt||!form.dueAt)return ElMessage.warning('请选择开始和截止时间');if(form.dueAt<=form.startAt)return ElMessage.warning('截止时间应晚于开始时间');if(!form.visibility.trim())return ElMessage.warning('请说明资料用途与可见范围');await run(async()=>{const c=await api('/collections',{method:'POST',body:form});createOpen.value=false;await refresh();collectionScope.value='current';collectionSearch.value='';clearRosterFilters();current.value=c;detailOpen.value=true;ElMessage.success('草稿已保存，请核对后发布')})}
async function act(c:any,action:string){if(['extend','reopen'].includes(action)){Object.assign(maintenance,{id:c.id,name:c.name,action,originalDueAt:c.dueAt,dueAt:'',reason:''});maintenanceOpen.value=true;return;}try{let extra:any={};if(action==='publish'){await ElMessageBox.confirm(`将发布“${c.name}”给 ${c.counts?Object.entries(c.counts).filter(([k])=>!['overdue','removed'].includes(k)).reduce((n,[,v])=>n+Number(v),0):c.roster.length} 名学生，截止时间为 ${fmt(c.dueAt)}。发布后，学生即可按设定的开始时间填写。`,'发布前核对');await run(async()=>{const updated=await api(`/collections/${c.id}/action`,{method:'POST',body:{action,reason:'核对名单后发布学生材料收集'}});if(current.value?.id===c.id)current.value=updated;await refresh();ElMessage.success('已发布给所选学生')});return;}const{value}=await ElMessageBox.prompt('填写操作原因','任务维护',{inputValidator:v=>!!v?.trim()||'必须填写原因'});if(action==='close'){const x=await ElMessageBox.prompt('未完成事项如何处理（例如联系核实后在关联任务补办）','关闭前处理',{inputValidator:v=>!!v?.trim()||'请说明未完成事项处理方式'});extra.unfinishedDisposition=x.value}await run(async()=>{const updated=await api(`/collections/${c.id}/action`,{method:'POST',body:{action,reason:value,...extra}});if(current.value?.id===c.id)current.value=updated;await refresh()})}catch{}}
async function saveMaintenance(){if(!maintenance.reason.trim())return ElMessage.warning('请填写调整原因');const due=maintenance.dueAt?new Date(maintenance.dueAt+'+08:00').getTime():0;if(maintenance.action==='extend'&&!due)return ElMessage.warning('请选择新的截止时间');if(maintenance.dueAt&&(!Number.isFinite(due)||due<=Date.now()))return ElMessage.warning('新的截止时间应晚于当前时间');if(maintenance.action==='extend'&&due<=new Date(maintenance.originalDueAt).getTime())return ElMessage.warning('新的截止时间应晚于原截止时间');await run(async()=>{const updated=await api(`/collections/${maintenance.id}/action`,{method:'POST',body:{action:maintenance.action,dueAt:maintenance.dueAt,reason:maintenance.reason.trim()}});if(current.value?.id===maintenance.id)current.value=updated;maintenanceOpen.value=false;await refresh();ElMessage.success('收集时间已更新')})}
async function saveAnswer(submit:boolean){if(uploadBusy.value)return ElMessage.warning('请等待附件上传完成');if(submit){for(const f of current.value.fields||[]){if(!f.required)continue;const v=answerValues[f.key];const empty=Array.isArray(v)?!v.length:(v===undefined||v===null||v==='');if(empty)return ElMessage.warning('请填写必填项："'+f.label+'"');}}await run(async()=>{await api(`/collections/${current.value.id}/answer`,{method:'PUT',body:{values:{...answerValues},submit,version:ownRow.value.answer.version}});current.value=await api(`/collections/${current.value.id}`);draftSaved.value=new Date().toLocaleTimeString('zh-CN');await refresh();ElMessage.success(submit?'提交成功，回执已生成':'草稿已保存到服务器')})}
async function review(approved:boolean){if(!reviewReason.value.trim())return ElMessage.warning(approved?'请填写审核通过说明':'请填写退回原因，便于学生修改');await run(async()=>{await api(`/collections/${current.value.id}/answers/${reviewRow.value.studentId}/review`,{method:'POST',body:{approved,reason:reviewReason.value}});reviewRow.value=undefined;reviewReason.value='';current.value=await api(`/collections/${current.value.id}`);await refresh();ElMessage.success('审核结果已保存')})}
async function changeRoster(){if(!rosterForm.studentId)return ElMessage.warning('请选择学生');if(!rosterForm.reason.trim())return ElMessage.warning('请填写调整原因');if(rosterForm.action==='supplement'&&!rosterForm.until)return ElMessage.warning('请选择补交截止时间');await run(async()=>{current.value=await api(`/collections/${current.value.id}/roster`,{method:'POST',body:rosterForm});rosterOpen.value=false;await refresh()})}
function copyTask(){Object.assign(form,{name:current.value.name+'（重新收交）',purpose:current.value.purpose,templateId:current.value.templateId,studentIds:current.value.roster.filter((r:any)=>r.status!=='removed').map((r:any)=>r.studentId),visibility:current.value.visibility,requiresReview:current.value.requiresReview,allowSupplement:current.value.allowSupplement,startAt:'',dueAt:''});createOpen.value=true}
async function startExport(){await run(async()=>{exportJob.value=await api(`/collections/${current.value.id}/exports`,{method:'POST'});ElMessage.success('已进入导出队列，稍后刷新进度')})}async function refreshExport(){await run(async()=>{exportJob.value=await api(`/collection-exports/${exportJob.value.id}`);if(exportJob.value.error)throw new Error(exportJob.value.error)})}
async function downloadExport(){await run(async()=>{const rows=await api<any[]>(`/collection-exports/${exportJob.value.id}/download`);const keys=Array.from(new Set(rows.flatMap(r=>Object.keys(r)))).filter(k=>k!=='studentId');const headings:Record<string,string>={studentNo:'学号',name:'姓名',className:'班级',rosterStatus:'名单状态',answerStatus:'提交状态',receipt:'提交回执'};const rowStates:Record<string,string>={required:'需要提交',exempt:'免交',removed:'已移出'};const csv='\ufeff'+[keys.map(k=>headings[k]||k),...rows.map(r=>keys.map(k=>k==='rosterStatus'?(rowStates[r[k]]||r[k]):k==='answerStatus'?answerLabel(r[k]):Array.isArray(r[k])?r[k].join('、'):r[k]))].map(r=>r.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=current.value.name+'-收交与附件清单.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
function fmt(t:string){return t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'—'}function stateLabel(s:string){return ({draft:'草稿',active:'进行中',expired:'已截止',closed:'已关闭 / 已归档',cancelled:'已取消 / 已归档'} as any)[s]||s}function answerLabel(s:string){return s==='draft'?'已保存草稿':categories[s]||s}onMounted(()=>{clockTimer=setInterval(()=>{now.value=Date.now()},30000);load()});onBeforeUnmount(()=>{if(clockTimer)clearInterval(clockTimer)});
